commands.command:
set -eu
cat > /tmp/infraset-nodejs.server.js.new <<'ANTRIEB_NODE_EOF'
'use strict';

var http = require('http');
var address = '127.0.0.1';
var port = 3000;
var responseBody = 'infraset-nodejs';

var server = http.createServer(function (request, response) {
  response.statusCode = 200;
  response.setHeader('Content-Type', 'text/plain');
  response.setHeader('Content-Length', Buffer.byteLength(responseBody));
  response.end(responseBody);
});

server.listen(port, address);

function shutdown() {
  server.close(function () {
    process.exit(0);
  });
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
ANTRIEB_NODE_EOF
sudo -n install -o root -g infraset-nodejs -m 0640 /tmp/infraset-nodejs.server.js.new /opt/infraset-nodejs/server.js
rm -f /tmp/infraset-nodejs.server.js.new
nodejs --check /opt/infraset-nodejs/server.js
stat -c '%U %G %a %n' /opt/infraset-nodejs/server.js

